// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // fuzzed params: from address, callee address (we will deploy a helper and use its address),
    // an array of addresses and a value v. We cannot fuzz dynamic arrays directly in signature
    // for Foundry easily, so we fuzz a bytes32 seed to derive array length and elements and v.
    function testFuzz_property(address from, bytes32 seed) public {
        // keep wide domain
        // derive array length in [1,4] because contract requires _tos.length > 0
        uint len = (uint(uint256(seed)) % 4) + 1;
        address[] memory tos = new address[](len);
        // populate tos with distinct addresses derived from seed
        for (uint i = 0; i < len; i++) {
            tos[i] = address(uint160(uint256(keccak256(abi.encodePacked(seed, i)))));
        }
        uint v = uint256(uint256(keccak256(abi.encodePacked(seed, "v"))));

        // Deploy a benign callee that will always succeed on the low-level call
        // It will implement transferFrom(address,address,uint256) and return nothing but not revert
        CalleeAlwaysSucceeds callee = new CalleeAlwaysSucceeds();

        // Call transfer on c and capture whether it returned true (reference) or false (mutant)
        bool ok;
        try c.transfer(from, address(callee), tos, v) returns (bool ret) {
            ok = ret;
        } catch {
            // if it reverts, the property is about successful completion, so treat as not-applicable
            // we set ok = true to avoid failing the assertion on reverts; the universal property
            // only concerns calls that complete successfully
            ok = true;
        }

        // The universal property: for any admissible inputs where the call completes,
        // the correct contract returns true. We assert that the observed return is true.
        // This will pass on reference C for all inputs and fail on the mutant for some inputs
        // (when the call completes but mutant returns false).
        assertTrue(ok);
    }
}

// Minimal adversarial helper: always succeeds for transferFrom selector calls
contract CalleeAlwaysSucceeds {
    // match selector transferFrom(address,address,uint256)
    function transferFrom(address, address, uint256) external pure returns (bool) {
        return true;
    }

    // fallback to accept any calldata: if called with selector via low-level call, return success
    fallback() external payable {
        // do nothing, just return successfully
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzz the 'from' actor and a dynamic array length and a value v
    function testFuzz_property(address from, uint256 v, uint8 tosLen) public {
        // keep tosLen reasonable but allow 1..10 to ensure non-empty arrays are tested
        uint8 len = tosLen % 10; // 0..9
        if (len == 0) { len = 1; } // ensure non-empty

        // deploy an innocuous callee that always returns true for the selector
        CalleeAccepting callee = new CalleeAccepting();

        // build tos array of helper contract addresses (they can be the same address repeated)
        address[] memory tos = new address[](len);
        for (uint i = 0; i < len; i++) { tos[i] = address(callee); }

        // call transfer and observe whether it returns (true) or reverts
        bool ok;
        try c.transfer(from, address(callee), tos, v) returns (bool ret) {
            ok = ret;
        } catch {
            ok = false; // if it reverts treat as false
        }

        // General fact: the reference implementation always returns true (ok == true) for any non-empty tos
        // (the mutant returns false immediately after the first successful call for some inputs)
        assertTrue(ok);
    }
}

// Minimal helper that accepts the low-level call with the expected selector
contract CalleeAccepting {
    // implement a function matching transferFrom(address,address,uint256)
    function transferFrom(address /*from*/, address /*to*/, uint256 /*amount*/) external pure returns (bool) {
        return true;
    }
    // fallback to accept any calls with the selector via low-level call
    fallback() external payable {
        // do nothing, allow the call to succeed
    }
}
